AUTH_BASE = """{% extends 'base.html' %}{% block title %}TITLE{% endblock %}{% block page_name %}PN{% endblock %}{% block body_class %}auth-body{% endblock %}{% block body %}<main class=\"auth-shell\"><section class=\"auth-art\"><h1>SocialHub</h1><p>Premium purple, pink and blue social experiences for modern creators.</p></section><section class=\"auth-panel\"><form class=\"auth-card\" id=\"FORMID\"><a class=\"brand\" href=\"/\"><span class=\"brand-mark\"><i class=\"fas fa-bolt\"></i></span><span>SocialHub</span></a><h2>HEADING</h2><p class=\"muted\">Accessible, secure and responsive authentication.</p>FIELDS<button class=\"btn btn-primary\" type=\"submit\">HEADING</button><a class=\"muted\" href=\"ALT\">Continue</a></form></section></main><div id=\"toast-container\" class=\"toast-container\" aria-live=\"polite\"></div><script src=\"/static/js/app.js\"></script>{% endblock %}"""
auths = [("login.html","login","Login - SocialHub","login-form","Login","<input class='form-control' name='email' id='email' type='email' placeholder='Email' required><div class='password-wrap'><input class='form-control' name='password' id='password' type='password' placeholder='Password' required><button class='btn btn-sm btn-secondary' type='button' data-action='toggle-password'>Show</button></div><label><input name='remember' type='checkbox' checked> Remember me</label>","/register"),("register.html","register","Register - SocialHub","register-form","Create account","<input class='form-control' name='full_name' id='full_name' placeholder='Full name'><input class='form-control' name='username' id='username' placeholder='Username' required><input class='form-control' name='email' id='email' type='email' placeholder='Email' required><div class='password-wrap'><input class='form-control' name='password' id='password' type='password' placeholder='Password' required minlength='6'><button class='btn btn-sm btn-secondary' type='button' data-action='toggle-password'>Show</button></div>","/login"),("forgot_password.html","forgot-password","Forgot Password - SocialHub","forgot-form","Send reset link","<input class='form-control' name='email' id='email' type='email' placeholder='Email address' required>","/login"),("reset_password.html","reset-password","Reset Password - SocialHub","reset-form","Reset password","<input type='hidden' name='token' id='token' value='{{ token }}'><div class='password-wrap'><input class='form-control' name='password' id='password' type='password' placeholder='New password' required><button class='btn btn-sm btn-secondary' type='button' data-action='toggle-password'>Show</button></div>","/login")]
for fn,pn,title,form,head,fields,alt in auths:
    w(T / fn, AUTH_BASE.replace("TITLE",title).replace("PN",pn).replace("FORMID",form).replace("HEADING",head).replace("FIELDS",fields).replace("ALT",alt))

